def backfill_customer(apps, schema_editor):
    """Point every existing usage at the customer that consumed it.

    The link already exists on visit / package_sale / welcome_pack_usage; this
    just copies it onto the row so per-customer consumption reporting works
    for history written before the column existed.
    """
    ProductUsage = apps.get_model('finance', 'ProductUsage')
    for relation in ('visit', 'package_sale', 'welcome_pack_usage'):
        pairs = (
            ProductUsage.objects
            .filter(customer__isnull=True, **{f'{relation}__isnull': False})
            .values_list('id', f'{relation}__customer_id')
        )
        ids_by_customer = {}
        for usage_id, customer_id in pairs:
            if customer_id:
                ids_by_customer.setdefault(customer_id, []).append(usage_id)
        for customer_id, usage_ids in ids_by_customer.items():
            ProductUsage.objects.filter(id__in=usage_ids).update(customer_id=customer_id)


def backfill_toman_snapshots(apps, schema_editor):
    """Restate historical USD costs in Toman at the rate each row recorded.

    Only rows with a usable exchange_rate_snapshot are touched; rows without
    one keep 0, which is what the API reports too.
    """
    ProductUsage = apps.get_model('finance', 'ProductUsage')
    qs = ProductUsage.objects.filter(
        models.Q(unit_cost_toman_snapshot=0) | models.Q(total_cost_toman_snapshot=0),
        exchange_rate_snapshot__isnull=False,
        exchange_rate_snapshot__gt=0,
    ).only(
        'id', 'unit_cost_usd_snapshot', 'total_cost_usd_snapshot',
        'unit_cost_toman_snapshot', 'total_cost_toman_snapshot', 'exchange_rate_snapshot',
    )
    changed = []
    for usage in qs.iterator():
        rate = usage.exchange_rate_snapshot
        unit_toman = (usage.unit_cost_usd_snapshot * rate).quantize(Decimal('0.01'))
        total_toman = (usage.total_cost_usd_snapshot * rate).quantize(Decimal('0.01'))
        if usage.unit_cost_toman_snapshot != unit_toman or usage.total_cost_toman_snapshot != total_toman:
            usage.unit_cost_toman_snapshot = unit_toman
            usage.total_cost_toman_snapshot = total_toman
            changed.append(usage)
    if changed:
        ProductUsage.objects.bulk_update(
            changed, ['unit_cost_toman_snapshot', 'total_cost_toman_snapshot'], batch_size=500,
        )


